def transform(grid):
    h, n = len(grid), len(grid[0])
    frame_color = grid[0][0]
    w = 0
    while w < n and grid[0][w] == frame_color:
        w += 1

    # Find the horizontal frame boundaries.
    boundaries = [
        r for r in range(h)
        if all(grid[r][c] == frame_color for c in range(w))
    ]

    # Extract connected colored objects to the right of the frame.
    unseen = {
        (r, c)
        for r in range(h)
        for c in range(w, n)
        if grid[r][c] not in (0, frame_color)
    }
    objects = []
    while unseen:
        start = unseen.pop()
        color = grid[start[0]][start[1]]
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if p in unseen and grid[p[0]][p[1]] == color:
                    unseen.remove(p)
                    comp.add(p)
                    stack.append(p)
        min_r = min(r for r, c in comp)
        min_c = min(c for r, c in comp)
        shape = frozenset((r - min_r, c - min_c) for r, c in comp)
        objects.append((color, shape))

    out = [row[:w] for row in grid]
    used = set()

    for top, bottom in zip(boundaries, boundaries[1:]):
        target_cells = {
            (r - top - 1, c - 1)
            for r in range(top + 1, bottom)
            for c in range(1, w - 1)
            if grid[r][c] == 0
        }
        if not target_cells:
            continue

        min_r = min(r for r, c in target_cells)
        min_c = min(c for r, c in target_cells)
        target_shape = frozenset(
            (r - min_r, c - min_c) for r, c in target_cells
        )

        for i, (color, shape) in enumerate(objects):
            if i not in used and shape == target_shape:
                used.add(i)
                for r in range(top + 1, bottom):
                    for c in range(1, w - 1):
                        if grid[r][c] == 0:
                            out[r][c] = color
                break

    return out
